import{_ as a,C as r,o as i,c as s,E as d,a2 as o}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"数字员工需要暂停保留型预算准入，而不是硬终止语义","description":"","frontmatter":{"title":"数字员工需要暂停保留型预算准入，而不是硬终止语义","date":"2026-08-08","column":"digital-employee","category":"daily","summary":"预算耗尽不应被简化为失败或终止。对长周期数字员工，更稳健的运行语义是阻止新的生成式工作、保留已接受状态、允许有限结算，并只在授权预算策略变化后恢复执行。","item_id":"Q-20260808-01","source_research_object":"research/analysis/Q-20260808-01-pause-preserving-budget-admission.md","source_reading_result":"research/reading/Q-20260808-01-session-budget-governance.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-08-pause-preserving-budget-admission-cover-v2.jpg"},"headers":[],"relativePath":"zh/digital-employee/2026-08-08-pause-preserving-budget-admission.md","filePath":"zh/digital-employee/2026-08-08-pause-preserving-budget-admission.md","lastUpdated":1787407830000}'),l={name:"zh/digital-employee/2026-08-08-pause-preserving-budget-admission.md"};function n(h,e,g,c,u,p){const t=r("ArticleCover");return i(),s("div",null,[d(t,{image:"/assets/covers/daily-2026-08-08-pause-preserving-budget-admission-cover-v2.jpg",kicker:"数字员工 · 每日研究",title:"数字员工需要暂停保留型预算准入，而不是硬终止语义",summary:"预算耗尽不应被简化为失败或终止。对长周期数字员工，更稳健的运行语义是阻止新的生成式工作、保留已接受状态、允许有限结算，并只在授权预算策略变化后恢复执行。",version:"Q-20260808-01",status:"Daily Runtime V5 · 2026-08-08",languageHref:"/en/digital-employee/2026-08-08-pause-preserving-budget-admission",languageLabel:"English"}),e[0]||(e[0]=o(' # 数字员工需要暂停保留型预算准入，而不是硬终止语义 <p>数字员工开始承担长周期、可恢复工作后，预算就不再只是报表里的一个数字，而会直接决定<strong>下一步工作是否还能被准入</strong>。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p>预算耗尽最稳健的工程语义不是 <code>failed</code>，也不是立即销毁会话，而是一个<strong>可逆的工作准入状态</strong>：新的生成式请求停止进入运行时，已经接受的工作状态被保留，必要的结算动作仍可完成，恢复则必须来自有权修改预算策略的主体。</p><p>这一定义来自 <code>Q-20260808-01</code> Research Object。Production 未重新读取 Signal Pool，也未从 Reading Result 开展新的分析。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文唯一分析输入是 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-01-pause-preserving-budget-admission.md" target="_blank" rel="noreferrer">Research Object — Pause-Preserving Budget Admission</a>。Reading Result 仅作为该对象已经声明的证据追溯入口，Production 未据此重新研究。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>Research Object 区分了几个很容易被 UI 合并掉的状态：预算策略、精确执行计量、面向运营者的显示值、新工作是否可准入、已经进入系统的结算工作，以及可恢复的长期工作状态。</p><p>这意味着“硬预算”需要谨慎解释。它可以是对<strong>新模型请求准入</strong>的硬门禁，却不自动等于最终账单的精确上限，因为门禁生效前已经接受的请求仍可能继续结算。类似地，预算触发暂停后，工作身份和历史仍然存在；它既不是业务完成，也不等于执行失败。</p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语义</th><th style="text-align:right;">允许新生成式工作</th><th style="text-align:right;">保留长期工作状态</th><th style="text-align:right;">允许有限结算</th><th style="text-align:right;">恢复需要授权</th></tr></thead><tbody><tr><td>普通 Running</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">否</td></tr><tr><td>BudgetPaused</td><td style="text-align:right;">否</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td></tr><tr><td>Failed</td><td style="text-align:right;">否</td><td style="text-align:right;">视实现而定</td><td style="text-align:right;">通常否</td><td style="text-align:right;">通常需要恢复流程</td></tr><tr><td>Completed</td><td style="text-align:right;">否</td><td style="text-align:right;">是</td><td style="text-align:right;">不应再产生新工作</td><td style="text-align:right;">不适用</td></tr></tbody></table><p>表格是 Research Center 基于 Research Object 的状态语义综合，不表示来源产品定义了同名状态机。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>真正值得工程化的不是“显示剩余预算”，而是把经济权限变成运行时准入条件。预算策略应绑定到长期 WorkOrder 或等价工作身份，由明确的策略所有者修改；执行器不能因为一次重试、重连或模型自我判断就恢复已经被预算门禁暂停的工作。</p><p>同时，精确执行计量与运营显示值应分开记录。Research Object 明确提醒：可见数值可能经过舍入，而执行门禁使用的量不应被运营 UI 的近似显示替代。若系统承诺“绝不超过某个最终金额”，就超出了当前证据边界。</p><p>共享预算还带来另一个治理问题：多个线程共用同一上限时，并不能天然得到角色、部门或任务级的独立责任归属。更高层的组织预算需要作为单独策略对象存在。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对数字员工运行时，建议把 <code>Active</code>、<code>BudgetPaused</code>、<code>WaitingForAuthority</code> 与 <code>Completed</code> 分开；保存预算策略所有者、执行计量、显示计量、暂停原因和恢复授权，并为已经开始的结算动作保留一个窄化 allowlist。</p><p>对 CodeFlowMu，这类暂停首先应落在 Runtime / WorkOrder 状态和观察界面中，而不是因为一个产品案例就扩展 FCoP 协议。恢复应从已接受的持久状态重新打开执行，而不是要求原 Provider session 继续存在。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>当前证据不支持几个更强结论：预算门禁不证明最终费用绝对不会超出阈值；公开 list cost 不等于企业最终账单；共享 session cap 不提供每线程预算；Exactly-once 事件、重连与组织级累计预算也没有被证明。</p><p>因此，本文的判断是“预算应治理工作准入”，不是“一个预算字段就能解决企业成本治理”。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>下一步应验证最小预算状态契约：cap、精确消耗、显示值、结算权限与恢复权限如何分离；角色预算如何与共享 WorkOrder 预算组合；崩溃后 BudgetPaused 与结算 receipt 如何恢复；以及 UI 是否需要独立的预算决策状态。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图把运行过程拆成 <code>Active → Budget Gate → BudgetPaused → Settlement Drain → Authorized Resume</code>。图中是 Research Center 基于 Research Object 的机制综合，不表达来源未提供的量化结果。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-01-pause-preserving-budget-admission.md" target="_blank" rel="noreferrer">Research Object — Pause-Preserving Budget Admission</a>：本文唯一分析输入，包含研究判断、不确定性、反证与工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260808-01-session-budget-governance.md" target="_blank" rel="noreferrer">Reading Result — Session Budget Governance</a>：Research Object 的证据追溯入口；Production 未从该文件重新开展研究。</li></ol>',29))])}const y=a(l,[["render",n]]);export{b as __pageData,y as default};
